import csv, numpy as np, sys
from math import gcd, log
from functools import reduce
from collections import Counter
from scipy.optimize import minimize
rows=list(csv.DictReader(open(sys.argv[1])))
K=4
N=len(rows)
F={k:np.zeros((N,K)) for k in "dist ud pd cop kin fkin rb pres ex t".split()}
sp=np.zeros(N);dh=np.zeros(N);ph=np.zeros(N);co=np.zeros(N);y=np.zeros(N);nn=np.zeros(N)
def coinc(ex):
    n=len(ex)
    if n<2: return 0.0
