    y[i]=int(r["rating"]);nn[i]=n
    for k,e in enumerate(ex):
        F["dist"][i,k]=abs(t-e)/10;F["ud"][i,k]=t%10!=e%10;F["pd"][i,k]=t%2!=e%2
        F["cop"][i,k]=(n>1 and g>=3 and t%g!=0);F["kin"][i,k]=(t%e==0 and t!=e and e>1)
