        F["ex"][i,k]=e;F["t"][i,k]=t
    if n>1:
        sp[i]=(max(ex)-min(ex))/100;dh[i]=(max(Counter(e%10 for e in ex).values())-1)/(n-1);ph[i]=(max(Counter(e%2 for e in ex).values())-1)/(n-1)
    else: sp[i]=dh[i]=ph[i]=.5
    co[i]=coinc(ex)
E=F["ex"];T=F["t"]
def nll(th,var):
    lcm,lcu,st,ht,cp,cd,sh,a,b,lwm,lwf,lwr=th[:12];ext=th[12:]
