    cm=np.exp(lcm-st*sp)[:,None];cu=np.exp(lcu+ht*dh)[:,None];cpar=(cp*ph)[:,None];gn=np.exp(sh*co)[:,None]
    ls=gn*(-cm*F["dist"]-cu*F["ud"]-cpar*F["pd"]-cd*F["cop"])
    kin=F["kin"].copy();fk=F["fkin"]
    if var=="gate12": kin=kin*(E<=12)
    elif var=="decay_e": kin=kin*np.exp(-np.exp(ext[0])*(E-2)/10)
    elif var=="tt_strength": kin=kin*((E<=12)+np.exp(ext[0])*(E>12))  # ext[0] log weight
