    elif var=="decay_e_plus": kin=kin*np.exp(-np.exp(ext[0])*np.maximum(E-ext[1],0)/10) 
    elif var=="gate10": kin=kin*(E<=10)
    elif var=="gate9": kin=kin*(E<=9)
    elif var=="loge": kin=kin*np.exp(-np.exp(ext[0])*np.log(np.maximum(E,2)/2))
